configuration.script:
// Berechnet die Ladezyklen (Vollzyklen) des Akkus.
// Grundlage: Register 35209 = vom Wechselrichter gezaehlte Gesamtentladung
// seit Installation, in 0,1 kWh (nicht vom BMS).
// Vollzyklen = Gesamtentladung (kWh) / nutzbare Kapazitaet (kWh)
//
// Nutzbare Kapazitaet: Pylontech Force H1 mit 6 Modulen = 20,24 kWh
// (Datenblatt: 6M nominal 21,31 kWh, nutzbar 20,24 kWh).
// Bei Erweiterung um Module diesen Wert anpassen.
val kapazitaetKWh = 20.24

if (Goodwe_Batt_Entladung_Raw.state instanceof Number) {
    val entladungKWh = (Goodwe_Batt_Entladung_Raw.state as Number).doubleValue / 10.0
    Akku_Entladung_Gesamt.postUpdate(entladungKWh)
    Akku_Ladezyklen.postUpdate(entladungKWh / kapazitaetKWh)
}

// Schaltet den GoodWe-Wechselrichter zwischen Netzladen und Automatik um.
// Entspricht:
//   EIN: 47512 = 3000 W, danach 47511 = 2 (Laden)
//   AUS: 47511 = 1 (Automatik), danach 47512 = 0
// Der Schalter selbst wird NICHT hier gesetzt, sondern nur durch die Regel
// "Netzladen Status", die den tatsaechlich gelesenen Modus anzeigt.
val ladeleistung = 3000

if (receivedCommand == ON) {
    Goodwe_EMS_Power.sendCommand(ladeleistung)
    Thread::sleep(300)
    Goodwe_EMS_Mode.sendCommand(2)
    logInfo("Netzladen", "Netzladen EIN angefordert: Mode 2, " + ladeleistung + " W")
} else {
    Goodwe_EMS_Mode.sendCommand(1)
    Thread::sleep(300)
    Goodwe_EMS_Power.sendCommand(0)
    logInfo("Netzladen", "Netzladen AUS angefordert: Mode 1 (Automatik), 0 W")
}

// Zeigt im Schalter immer den tatsaechlichen Zustand des Wechselrichters an.
// Register 47511 wird alle 2 Sekunden gelesen. Steht es auf 2 (Laden),
// ist der Schalter AN, sonst AUS - unabhaengig davon, was zuletzt geklickt wurde.
if (Goodwe_EMS_Mode.state instanceof Number) {
    val soll = if ((Goodwe_EMS_Mode.state as Number).intValue == 2) ON else OFF
    if (Goodwe_Netzladen.state != soll) {
        Goodwe_Netzladen.postUpdate(soll)
        logInfo("Netzladen", "Status vom Wechselrichter: EMS Mode " + Goodwe_EMS_Mode.state + " -> Schalter " + soll)
    }
}

// Arbeitszahl heute (Tages-COP) der Vitocal 250-A:
// erzeugte Waerme heute / aufgenommener Strom heute, jeweils Heizen + Warmwasser.
// Grundlage sind die Tageszaehler der Viessmann-API (heat.production.summary und
// power.consumption.summary). Sie beginnen um Mitternacht wieder bei 0. Solange
// weniger als 0,1 kWh Strom gezaehlt sind, bleibt der Wert leer (sonst springt er wild).
var double strom = 0.0
var double waerme = 0.0
if (WP_Strom_Heizen_Heute.state instanceof Number) strom = strom + (WP_Strom_Heizen_Heute.state as Number).doubleValue
if (WP_Strom_Warmwasser_Heute.state instanceof Number) strom = strom + (WP_Strom_Warmwasser_Heute.state as Number).doubleValue
if (WP_Waerme_Heizen_Heute.state instanceof Number) waerme = waerme + (WP_Waerme_Heizen_Heute.state as Number).doubleValue
if (WP_Waerme_Warmwasser_Heute.state instanceof Number) waerme = waerme + (WP_Waerme_Warmwasser_Heute.state as Number).doubleValue

if (strom >= 0.1) {
    WP_COP_Heute.postUpdate(waerme / strom)
} else {
    WP_COP_Heute.postUpdate(NULL)
}

// Status der elektrischen Zusatzheizung (Heizstab) der Vitocal 250-A.
// Das API-Feld heating.heatingRod "active" meldet nur, ob der Heizstab freigegeben ist,
// nicht ob er gerade heizt. Der Status wird deshalb aus den Zaehlern abgeleitet:
// Steigt der Tagesverbrauch des Heizstabs (Heizen oder Warmwasser) oder seine Startzahl,
// heizt er -> AN. Kommt 15 Minuten lang kein Anstieg mehr -> AUS.
// Um Mitternacht fallen die Tageszaehler auf 0, das wird ignoriert.
if (!(previousState instanceof Number) || !(newState instanceof Number)) return;
if ((newState as Number).doubleValue <= (previousState as Number).doubleValue) return;

WP_Zusatzheizung.postUpdate(ON)
val alterTimer = privateCache.get("ausTimer") as Timer
alterTimer?.cancel()
privateCache.put("ausTimer", createTimer(now.plusMinutes(15), [ |
    WP_Zusatzheizung.postUpdate(OFF)
]))

// Nach einem Neustart laeuft kein Abschalt-Timer. Damit ein wiederhergestellter
// Zustand AN nicht haengen bleibt, beginnt die Anzeige mit AUS.
WP_Zusatzheizung.postUpdate(OFF)
